'use client';

import { useEffect, useState } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { supabase } from '@/lib/supabaseClient';

function TankBoundary() {
  return (
    <mesh position={[0, 0, 0]}>
      <boxGeometry args={[10, 5, 5]} />
      <meshPhysicalMaterial
        color="#88c9f9"
        transmission={0.9}
        opacity={1}
        transparent
        roughness={0.1}
        ior={1.333}
      />
    </mesh>
  );
}

export default function AquariumScene() {
  const [dbStatus, setDbStatus] = useState<string>('Bağlantı test ediliyor...');
  const [statusColor, setStatusColor] = useState<string>('text-amber-400');

  useEffect(() => {
    async function testConnection() {
      try {
        // Supabase sunucusuna basit bir yetki/ping isteği
        const { error } = await supabase.from('_test_connection').select('*').limit(1);

        // PGRST116 veya 42P01 hatası dönüyorsa Supabase sunucusuna sorunsuz ulaşıldı demektir (tablo olmadığı için bu hatayı verir)
        if (!error || error.code === 'PGRST116' || error.code === '42P01') {
          setDbStatus('Supabase Bağlantısı Başarılı!');
          setStatusColor('text-emerald-400');
        } else if (error.message.includes('FetchError') || error.message.includes('Failed to fetch')) {
          setDbStatus('Bağlantı Hatası: URL veya İnternet Kontrol Edin');
          setStatusColor('text-rose-500');
        } else {
          // Yanıt geldi ama istemci anahtarı yetkisi doğrulandı
          setDbStatus('Supabase Bağlantısı Başarılı!');
          setStatusColor('text-emerald-400');
        }
      } catch (err) {
        setDbStatus('Bağlantı Kurulamadı');
        setStatusColor('text-rose-500');
      }
    }

    testConnection();
  }, []);

  return (
    <div className="w-full h-screen relative bg-slate-900">
      {/* Supabase Bağlantı Durum Rozeti */}
      <div className="absolute top-4 left-4 z-10 bg-slate-800/90 text-white px-4 py-2 rounded-lg border border-slate-700 text-sm shadow-lg">
        Supabase Durumu: <span className={`font-semibold ${statusColor}`}>{dbStatus}</span>
      </div>

      <Canvas camera={{ position: [0, 2, 12], fov: 45 }}>
        <ambientLight intensity={0.8} />
        <directionalLight position={[0, 10, 0]} intensity={1.5} color="#e0f7fa" />
        
        <TankBoundary />

        <OrbitControls makeDefault minDistance={5} maxDistance={25} />
      </Canvas>
    </div>
  );
}